---------------------------------------------------------------------------------------------------
-- Description
---------------------------------------------------------------------------------------------------
-- VUnit wrapper executing the plain VHDL (non-VUnit) testbench generated by olo_fix_lin_approx.
-- The plain testbench reports mismatches and timeouts with severity error, which fails the test.

---------------------------------------------------------------------------------------------------
-- Libraries
---------------------------------------------------------------------------------------------------
library ieee;
    use ieee.std_logic_1164.all;

library vunit_lib;
    context vunit_lib.vunit_context;

---------------------------------------------------------------------------------------------------
-- Entity
---------------------------------------------------------------------------------------------------
-- vunit: run_all_in_same_sim
entity olo_fix_lin_approx_plain_tb is
    generic (
        runner_cfg : string
    );
end entity;

architecture sim of olo_fix_lin_approx_plain_tb is

begin

    -----------------------------------------------------------------------------------------------
    -- TB Control
    -----------------------------------------------------------------------------------------------
    test_runner_watchdog(runner, 1 ms);

    p_control : process is
    begin
        test_runner_setup(runner, runner_cfg);

        while test_suite loop

            -- The plain testbench runs on its own and ends itself (by timeout at the latest)
            if run("PlainTb") then
                wait for 100 us;
            end if;

        end loop;

        -- TB done
        test_runner_cleanup(runner);
    end process;

    -----------------------------------------------------------------------------------------------
    -- Plain Testbench
    -----------------------------------------------------------------------------------------------
    i_plain_tb : entity work.olo_fix_lin_approx_tanh_plain_tb;

end architecture;
